#[derive(Clone)]struct NativeChild(Arc<Mutex<Child>>);
impl NativeChild{fn id(&self)->u32{self.0.lock().unwrap().id()}fn try_wait(&self)->std::io::Result<Option<std::process::ExitStatus>>{self.0.lock().unwrap().try_wait()}}
struct NativeWatch{child:NativeChild,root:std::path::PathBuf,view:scheduler::Handle<Protected>}
fn safe_diagnostic(value:&str)->String{let lower=value.to_ascii_lowercase();if value.len()>240||value.chars().any(char::is_control)||["token","secret","password","proof","authorization","bearer"].iter().any(|word|lower.contains(word))||value.split(|c:char|!c.is_ascii_alphanumeric()&&c!='_'&&c!='-').any(|word|word.len()>=40){"redacted; inspect retained native-output.txt".into()}else{value.into()}}
fn original_native_error(path:&std::path::Path)->String{let Ok(mut file)=std::fs::File::open(path)else{return "native log unavailable".into()};let size=file.metadata().map(|m|m.len().min(16384)).unwrap_or(0);if file.seek(SeekFrom::End(-(size as i64))).is_err(){return "native log unavailable".into()}let mut bytes=Vec::new();if file.take(16384).read_to_end(&mut bytes).is_err(){return "native log unavailable".into()}for line in String::from_utf8_lossy(&bytes).lines(){if let Some((source,rest))=line.split_once(".lua:"){if let Some((number,message))=rest.split_once(':'){if !number.is_empty()&&number.bytes().all(|b|b.is_ascii_digit()){let source=source.rsplit(['/', '\\']).next().unwrap_or("native");return format!("{}.lua:{}: {}",safe_diagnostic(source),number,safe_diagnostic(message.trim()))}}}}"no safe Lua error line; inspect retained native-output.txt".into()}
impl NativeWatch{fn failure(&self,label:&str)->Option<String>{let transport=self.root.parent().unwrap().parent().unwrap().join("network-first-transport-loss.json");if transport.is_file(){return Some(format!("First unexplained transport event; {}",transport.display()))}let first=self.root.join("first-unexpected-hold.json");if let Ok(bytes)=std::fs::read(&first){if let Ok(native)=serde_json::from_slice::<Value>(&bytes){let run=self.root.parent().unwrap().parent().unwrap();let output=run.join("initial-first-loss.json");if !output.exists(){std::fs::write(&output,serde_json::to_vec_pretty(&json!({"label":safe_diagnostic(label),"native":native,"current_app":self.view.view(),"nativeRoot":self.root,"unchangedDeadlines":true})).unwrap()).unwrap();}return Some(format!("First native control-loss edge after initial Playing; {}",output.display()))}}match self.child.try_wait(){Ok(Some(status))=>{let view=self.view.view();Some(format!("Native child exited during {label}: status={status}; original={}; state={}; reason={}; log={}",original_native_error(&self.root.join("native-output.txt")),safe_diagnostic(view["connection"]["state"].as_str().unwrap_or("unavailable")),safe_diagnostic(view["connection"]["reason"].as_str().unwrap_or("none")),self.root.join("native-output.txt").display()))},Ok(None)=>None,Err(_)=>Some("Native child status unavailable".into())}}}
fn check_natives(watches:&Arc<Mutex<Vec<NativeWatch>>>,label:&str){let error={let watches=watches.lock().unwrap();watches.iter().find_map(|watch|watch.failure(label))};if let Some(error)=error{panic!("{error}")}}
#[derive(Default)]struct ProtectedScope(Arc<Mutex<Vec<Protected>>>);
impl ProtectedScope{fn clone(&self)->Arc<Mutex<Vec<Protected>>>{self.0.clone()}fn lock(&self)->std::sync::LockResult<std::sync::MutexGuard<'_,Vec<Protected>>>{self.0.lock()}}
impl Drop for ProtectedScope{fn drop(&mut self){for store in self.0.lock().unwrap().iter(){let _=store.0.cleanup();}}}
// Fixture engine coverage and canonical service room mode are separate choices.
fn lc1_service_room_args(race_engine:bool,core_room:bool,race_config:Option<&str>)->Result<Vec<String>,&'static str>{
 if race_config.is_some()&&(core_room||!race_engine){return Err("Race configuration requires a Race service room; NT2_LC1_CORE_ROOM conflicts with race-config.json")}
 let mut args=vec![];
 if race_engine&&!core_room{args.push("--race".into());}
 if let Some(path)=race_config{args.extend(["--race-config".into(),path.into()]);}
 Ok(args)
}
#[test]fn lc1_service_room_arguments_preserve_race_defaults_and_allow_core_engine_coverage(){
 assert_eq!(lc1_service_room_args(false,false,None).unwrap(),Vec::<String>::new());
 assert_eq!(lc1_service_room_args(true,false,None).unwrap(),vec!["--race"]);
 assert_eq!(lc1_service_room_args(true,false,Some("owned/race-config.json")).unwrap(),vec!["--race","--race-config","owned/race-config.json"]);
 assert!(lc1_service_room_args(true,true,None).unwrap().is_empty());
 assert!(lc1_service_room_args(false,true,None).unwrap().is_empty());
 assert!(lc1_service_room_args(true,true,Some("owned/race-config.json")).is_err());
 assert!(lc1_service_room_args(false,false,Some("owned/race-config.json")).is_err());
}
struct Service{root:std::path::PathBuf,child:Child,events:mpsc::Receiver<Value>,descriptor:std::path::PathBuf,id:u64,closed:bool,clock:Instant,clock_probe:Option<network_profile::ClockProbe>,trace_movement:bool,watches:Arc<Mutex<Vec<NativeWatch>>>,stores:ProtectedScope}
impl Service{
 fn start(root:&std::path::Path)->Self{verify_current_fixture_inputs();let race_config=root.join("race-config.json");let room_args=lc1_service_room_args(std::env::var("NT2_RACE_FIXTURE").as_deref()==Ok("1"),std::env::var("NT2_LC1_CORE_ROOM").as_deref()==Ok("1"),race_config.is_file().then(||race_config.to_str().unwrap())).expect("Consistent fixture room selection");let log=std::fs::File::create(root.join("service-stderr.txt")).unwrap();let mut child=hidden("C:/Program Files/nodejs/node.exe").current_dir(repo()).args(["--import","tsx","apps/service/scripts/lifecycle-lc1-fixture-host.ts"]).args(room_args).args(if std::env::var("NT2_ITEM_FIXTURE").as_deref()==Ok("1"){vec!["--items"]}else if std::env::var("NT2_B1_FIXTURE").as_deref()==Ok("1"){vec!["--b1-gold"]}else{vec![]}).args(["--runtime",&profile_path(),"--runtime-sha256",nt2_desktop_g0::g3_social_installation::DEVELOPMENT_SHA]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(log).spawn().unwrap();let out=child.stdout.take().unwrap();let(tx,events)=mpsc::channel();let captured=std::fs::File::create(root.join("service-controls.jsonl")).unwrap();std::thread::spawn(move||{let mut captured=captured;for line in BufReader::new(out).lines(){let Ok(line)=line else{break};let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};writeln!(captured,"{v}").unwrap();let _=tx.send(v);}});let until=Instant::now()+Duration::from_secs(45);let descriptor=loop{let v=events.recv_timeout(until.saturating_duration_since(Instant::now())).expect("Fixture readiness deadline");if v["event"]=="ready"{break std::path::PathBuf::from(v["privateDescriptor"].as_str().unwrap())}};Self{root:root.to_path_buf(),child,events,descriptor,id:0,closed:false,clock:Instant::now(),clock_probe:None,trace_movement:false,watches:Arc::new(Mutex::new(Vec::new())),stores:ProtectedScope::default()}}
 fn private(&self)->Value{serde_json::from_slice(&std::fs::read(&self.descriptor).unwrap()).unwrap()}
 fn command(&mut self,mut q:Value)->Value{
  let until=Instant::now()+Duration::from_secs(15);
  // Only the private read-only C1 audit may retry a positively correlated
  // capacity refusal. Gameplay, rule writes and unknown outcomes never retry here.
  for attempt in 0..4{
   self.id+=1;q["id"]=json!(self.id);writeln!(self.child.stdin.as_mut().unwrap(),"{q}").unwrap();self.child.stdin.as_mut().unwrap().flush().unwrap();
   loop{check_natives(&self.watches,"fixture control wait");assert!(Instant::now()<until,"Fixture control deadline");
    let v=match self.events.recv_timeout(until.saturating_duration_since(Instant::now()).min(Duration::from_millis(250))){Ok(v)=>v,Err(mpsc::RecvTimeoutError::Timeout)=>continue,Err(_)=>panic!("Fixture control channel closed")};
    if v["id"]!=self.id{continue}
    if q["op"]=="c1Status"&&v["event"]=="error"&&v["code"]=="CAPACITY"&&attempt<3{std::thread::sleep(Duration::from_millis(250));break}
    assert_ne!(v["event"],"error","Fixture control refused: op={} code={}",safe_diagnostic(q["op"].as_str().unwrap_or("unknown")),safe_diagnostic(v["code"].as_str().unwrap_or("unknown")));
    if v.get("clock").is_some(){if let Some(probe)=self.clock_probe.as_mut(){probe.observe(&q,&v).unwrap();}}return v
   }
  }
  unreachable!("Last control attempt returns or reports its failure")
 }
 fn wall_clock(&mut self){check_natives(&self.watches,"ordinary scheduler wait");let now=Instant::now();let ms=now.duration_since(self.clock).as_millis() as u64;self.clock=now;if ms>0{self.command(json!({"op":"advance","ms":ms.min(3600000),"kind":"wall"}));}}
 fn capture_failure_diagnostics(&mut self){
  // Failure-only control reads deliberately skip the already-failed native
  // guard. No caller resumes; retained firstRetire survives cooperative unwind.
  let mut replies=serde_json::Map::new();
  let mut diagnostics=vec!["clockStatus","liveCapacityStatus","liveAuthStatus"];
  if std::env::var("NT2_ITEM_FIXTURE").as_deref()==Ok("1"){diagnostics.push("goldStatus");}
  for op in diagnostics{
   self.id+=1;let id=self.id;let request=json!({"id":id,"op":op});
   let sent=self.child.stdin.as_mut().is_some_and(|input|writeln!(input,"{request}").and_then(|_|input.flush()).is_ok());
   if !sent{replies.insert(op.into(),json!({"capture_error":"fixture control stdin unavailable"}));continue}
   let until=Instant::now()+Duration::from_secs(3);
   let result=loop{match self.events.recv_timeout(until.saturating_duration_since(Instant::now())){Ok(v)if v["id"]==id=>break v,Ok(_)=>{if Instant::now()>=until{break json!({"capture_error":"diagnostic reply deadline"})}},Err(_)=>break json!({"capture_error":"diagnostic reply unavailable"})}};
   replies.insert(op.into(),result);
  }
  let value=json!({"capture_boundary":"failure unwind before service EOF; not a simultaneous app/native snapshot","retained_first_event":"network-first-transport-loss.json or other first-loss receipt","diagnostics":replies});
  if let Ok(bytes)=serde_json::to_vec_pretty(&value){let _=std::fs::write(self.root.join("network-failure-service-diagnostics.json"),bytes);}
 }
 fn close(&mut self){if self.closed{return}self.command(json!({"op":"close"}));self.child.stdin.take();let until=Instant::now()+Duration::from_secs(15);loop{if let Some(status)=self.child.try_wait().unwrap(){assert!(status.success());break}assert!(Instant::now()<until,"Fixture cooperative cleanup did not finish; no termination");std::thread::sleep(Duration::from_millis(10));}for store in self.stores.lock().unwrap().iter(){assert_eq!(store.0.cleanup()["passed"],true,"Owned fixture credential cleanup failed");}self.closed=true;}
}
impl Drop for Service{fn drop(&mut self){if !self.closed{self.capture_failure_diagnostics();for store in self.stores.lock().unwrap().iter(){let _=store.0.cleanup();}self.child.stdin.take();let until=Instant::now()+Duration::from_secs(15);while Instant::now()<until{if self.child.try_wait().ok().flatten().is_some(){break}std::thread::sleep(Duration::from_millis(20));}}}}

/// Real Windows protected credentials, confined to one random fixture issuer.
/// Tracks and deletes only keys written by this disposable run.
#[derive(Clone)]struct Protected(Arc<ProtectedInner>);
struct ProtectedInner{origin:String,service:String,keys:Mutex<Vec<ServiceProfile>>,sizes:Mutex<std::collections::BTreeMap<uuid::Uuid,usize>>,writes:AtomicU64,last_error:Mutex<Option<String>>,closed:std::sync::atomic::AtomicBool,cleanup_path:Mutex<Option<std::path::PathBuf>>,world_files:Mutex<Option<Arc<nt2_desktop_g0::world_store::Files>>>}
impl ProtectedInner{fn cleanup(&self)->Value{let keys=self.keys.lock().unwrap();self.closed.store(true,Ordering::Release);let mut absent=0;let mut errors=Vec::new();for key in keys.iter(){assert_eq!(key.origin(),self.origin);assert_eq!(key.service_id(),self.service);if let Err(e)=crate::secrets::WindowsCredentialStore.delete(key){if errors.len()<4{errors.push(e.to_string());}}match crate::secrets::WindowsCredentialStore.load(key){Ok(None)=>absent+=1,Ok(Some(_))=>{if errors.len()<4{errors.push("Owned fixture key remains after delete".into());}},Err(e)=>{if errors.len()<4{errors.push(e.to_string());}}}}let file_cleanup=self.world_files.lock().unwrap().as_ref().map(|s|s.cleanup_fixture().unwrap_or_else(|e|json!({"passed":false,"error":e})));let file_ok=file_cleanup.as_ref().is_none_or(|v|v["passed"]==true);let result=json!({"world_files":file_cleanup,"tracked_owned_keys":keys.len(),"verified_absent":absent,"closed_to_writes":true,"errors":errors,"passed":absent==keys.len()&&errors.is_empty()&&file_ok});if let Some(path)=self.cleanup_path.lock().unwrap().as_ref(){let _=std::fs::write(path,serde_json::to_vec(&result).unwrap());}result}}
impl Drop for ProtectedInner{fn drop(&mut self){let _=self.cleanup();}}
impl Protected{fn new(origin:&str,service:&str)->Self{let url=reqwest::Url::parse(origin).unwrap();assert_eq!(url.host_str(),Some("127.0.0.1"));assert_ne!(url.port(),Some(4358));Self(Arc::new(ProtectedInner{origin:origin.into(),service:service.into(),keys:Mutex::new(Vec::new()),sizes:Mutex::new(std::collections::BTreeMap::new()),writes:AtomicU64::new(0),last_error:Mutex::new(None),closed:std::sync::atomic::AtomicBool::new(false),cleanup_path:Mutex::new(None),world_files:Mutex::new(None)}))}fn check(&self,p:&ServiceProfile){assert_eq!(p.origin(),self.0.origin);assert_eq!(p.service_id(),self.0.service);}fn snapshot(&self)->Value{let keys=self.0.keys.lock().unwrap();let sizes=self.0.sizes.lock().unwrap();json!({"tracked_owned_keys":keys.len(),"written_owned_keys":sizes.len(),"written_blob_bytes":sizes.values().sum::<usize>(),"max_blob_bytes":sizes.values().max(),"writes":self.0.writes.load(Ordering::Acquire),"last_error":self.0.last_error.lock().unwrap().clone(),"closed_to_writes":self.0.closed.load(Ordering::Acquire)})}}
impl CredentialStore for Protected{
 fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{self.check(p);let mut keys=self.0.keys.lock().unwrap();if self.0.closed.load(Ordering::Acquire){return Err(crate::secrets::StoreError::Unavailable)}if !keys.contains(p){keys.push(p.clone());}self.0.writes.fetch_add(1,Ordering::AcqRel);let result=crate::secrets::WindowsCredentialStore.save(p,b);if let Err(e)=&result{*self.0.last_error.lock().unwrap()=Some(e.to_string());}else{self.0.sizes.lock().unwrap().insert(p.profile_id(),b.bytes().len());}result}
 fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.check(p);crate::secrets::WindowsCredentialStore.load(p)}
 fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.check(p);let result=crate::secrets::WindowsCredentialStore.delete(p);if result.is_ok(){self.0.sizes.lock().unwrap().remove(&p.profile_id());}result}
}
