 let descriptor=std::fs::canonicalize(std::env::var("NT2_INTERRUPTED_CLEANUP_DESCRIPTOR").unwrap()).unwrap();let private:Value=serde_json::from_slice(&std::fs::read(&descriptor).unwrap()).unwrap();let schema=std::env::var("NT2_INTERRUPTED_CLEANUP_SCHEMA").unwrap();assert_eq!(private["namespace"],schema);
 let rows:Vec<Value>=std::fs::read_to_string(run.join("service-controls.jsonl")).unwrap().lines().map(|line|serde_json::from_str(line).unwrap()).collect();assert!(rows.iter().any(|v|v["allocatedFixtureSchema"]==schema&&v["databaseTarget"]=="127.0.0.1:54328/nt2_g1"));let ready=rows.iter().find(|v|v["event"]=="ready").unwrap();assert_eq!(std::fs::canonicalize(ready["privateDescriptor"].as_str().unwrap()).unwrap(),descriptor);
 let(origin,service)=(private["origin"].as_str().unwrap(),private["serviceId"].as_str().unwrap());let mut results=Vec::new();
 for side in ["host","peer"]{
  let own=run.join(side);let last:Value=serde_json::from_str(std::fs::read_to_string(own.join("boundary-snapshots.jsonl")).unwrap().lines().last().unwrap()).unwrap();assert_eq!(last["protected_store"]["tracked_owned_keys"],1);
  let store=Protected::new(origin,service);let device=uuid::Uuid::parse_str(if side=="host"{private["deviceId"].as_str().unwrap()}else{private["peer"]["deviceId"].as_str().unwrap()}).unwrap();
  let core=Core::new(store.clone(),device,Arc::new(Mutex::new(None)),own.join("claims"));let key=core.credential_profile(origin,service).unwrap();store.0.keys.lock().unwrap().push(key);*store.0.cleanup_path.lock().unwrap()=Some(own.join("protected-cleanup.json"));*store.0.world_files.lock().unwrap()=Some(Arc::new(nt2_desktop_g0::world_store::Files::fixture_reopen(own.join("world-records")).unwrap()));
  let result=store.0.cleanup();assert_eq!(result["passed"],true,"{side} exact owned cleanup failed: {result}");assert_eq!(result["tracked_owned_keys"],1);assert_eq!(result["verified_absent"],1);results.push(json!({"side":side,"cleanup":result}));
 }
 let result=json!({"passed":true,"ownerAuthorizedInterruptedCleanup":true,"namespace":schema,"credentialEnumeration":false,"databaseTouched":false,"results":results});std::fs::write(run.join("client-interrupted-cleanup.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();eprintln!("PASS exact interrupted fixture cleanup: two owned auth keys verified absent; owned world files removed; diagnostic evidence preserved");
