 fn close(&mut self){if self.birth!=0{self.routes.remove(self.owner,self.birth);}self.watches.lock().unwrap().retain(|watch|!Arc::ptr_eq(&watch.child.0,&self.child.0));fixture_input_write(self.root.join("stop"),b"cooperative fixture exit").unwrap();let until=Instant::now()+Duration::from_secs(8);loop{if let Some(status)=self.child.try_wait().unwrap(){assert!(status.success(),"{}",NativeWatch{child:self.child.clone(),root:self.root.clone(),view:self.view.clone()}.failure("cooperative close").unwrap());break}assert!(Instant::now()<until,"Native cooperative exit deadline; no termination");std::thread::sleep(Duration::from_millis(10));}}
