fn boundary_snapshot(client:&Client,label:&str){let v=client.handle.view();let common=client.pending.try_lock().map(|slot|crate::pipe::collection_view(&slot)).unwrap_or_else(|_|json!({"busy":true}));let native=client.diagnostics.try_lock().map(|d|d.view()).unwrap_or_else(|_|json!({"busy":true}));let snapshot=json!({"label":safe_diagnostic(label),"state":v["connection"]["state"],"reason":v["connection"]["reason"].as_str().map(safe_diagnostic),"connection":v["connection"],"auth_error":v["auth_error"].as_str().map(safe_diagnostic),"auth":v["auth_diagnostic"],"g3":v["g3"],"world_store":client.world_files.snapshot(),"protected_store":client.store.snapshot(),"common":common,"early":native["early_world"],"collection":native["lc1_collection_trace"],"recent_collection":native["lc1_collection_recent"],"lifecycle":v["lc1_lifecycle"],"retirement":native["lc1_retirement_trace"]});let mut out=std::fs::OpenOptions::new().create(true).append(true).open(client.root.join("boundary-snapshots.jsonl")).unwrap();writeln!(out,"{snapshot}").unwrap();}
async fn wait(service:&mut Service,client:&Client,label:&str,seconds:u64,predicate:impl Fn(&Value)->bool){wait_traced(service,client,None,label,seconds,predicate).await;}
async fn wait_traced(service:&mut Service,client:&Client,other:Option<&Client>,label:&str,seconds:u64,predicate:impl Fn(&Value)->bool){let until=Instant::now()+Duration::from_secs(seconds);let mut next=Instant::now();loop{service.wall_clock();if Instant::now()>=next{boundary_snapshot(client,label);if service.trace_movement{network_profile::recovery_owner_trace(client,label).await;if let Some(other)=other{network_profile::recovery_owner_trace(other,label).await;}}next=Instant::now()+Duration::from_secs(2);}let v=current_snapshot(client,None).await;if predicate(&v){write_current(client,label,&v);boundary_snapshot(client,&format!("passed: {label}"));return}if Instant::now()>=until&&std::env::var("NT2_RACE_FIXTURE").as_deref()==Ok("1"){let status=service.command(json!({"op":"raceStatus"}));std::fs::write(service.root.join("race-failure-status.json"),serde_json::to_vec_pretty(&status).unwrap()).unwrap();}assert!(Instant::now()<until,"LC1 {label} deadline; state={} reason={}; boundary={}",v["connection"]["state"],v["connection"]["reason"],client.root.join("boundary-snapshots.jsonl").display());tokio::time::sleep(Duration::from_millis(250)).await;}}

struct InspectionScan{desktop:String,world:String,attachment:String,instance:String,after:String,pages:u8}
impl InspectionScan{
 fn request(&mut self,mut q:wire::Request)->Result<wire::Request,String>{if self.pages>=32{return Err("Paused inspection page bound".into())}self.pages+=1;q.inspection_list=Some(wire::InspectionList{limit:Some(1),after_desktop_id:(!self.after.is_empty()).then(||self.after.clone())});Ok(q)}
 fn page(&mut self,r:wire::Response)->Result<(Option<Value>,bool),String>{
  let rows=r.inspections.unwrap_or_default();let next=r.inspection_next_desktop_id.unwrap_or_default();if rows.len()>1{return Err("Paused inspection exceeded canonical page size".into())}
  if !next.is_empty()&&(rows.first().and_then(|r|r.desktop_id.as_deref())!=Some(next.as_str())||next<=self.after||uuid::Uuid::parse_str(&next).is_err()){return Err("Paused inspection cursor did not advance canonically".into())}
  if rows.first().is_some_and(|r|r.desktop_id.as_ref().is_none_or(|id|!self.after.is_empty()&&id<=&self.after)){return Err("Paused inspection page regressed".into())}
  let selected=if let Some(row)=rows.into_iter().find(|r|r.desktop_id.as_deref()==Some(&self.desktop)){
   if row.world_token.as_deref()!=Some(&self.world)||row.attachment_id.as_deref()!=Some(&self.attachment)||row.game_instance_id.as_deref()!=Some(&self.instance){return Err("Paused inspection differs from current world owner".into())}
   Some(json!([row.observation_revision,row.content_digest,row.captured_at,row.attachment_id]))
  }else{None};self.after=next;Ok((selected,!self.after.is_empty()))
 }
}
async fn current_paused_inspection<S:CredentialStore+'static>(c:&mut Core<S>,world:&str)->Result<Value,String>{
 let desktop=c.desktop.as_ref().ok_or("Paused desktop absent")?;let game=c.game.as_ref().ok_or("Paused game owner absent")?;let owner=game.owner;let generation=c.generation.load(Ordering::Acquire);
 if c.world.record.as_ref().is_none_or(|r|r.world.to_string()!=world||r.intent!=nt2_desktop_g0::world_local::Intent::Rejoin){return Err("Paused world association changed".into())}
 let mut scan=InspectionScan{desktop:desktop.id.clone(),world:world.into(),attachment:game.session.attachment.clone(),instance:game.instance.clone(),after:String::new(),pages:0};
 loop{let q=scan.request(c.request(false))?;let response=c.rpc(&q,false,false).await?;
  if c.generation.load(Ordering::Acquire)!=generation||c.pending.lock().unwrap().as_ref().is_none_or(|p|p.owner!=Some(owner)||!c.native_authority_valid(p)){return Err("Paused inspection native owner retired".into())}
  let(selected,more)=scan.page(response)?;if let Some(selected)=selected{return Ok(selected)}if !more{return Err("Paused current world inspection absent".into())}
 }
}
async fn paused_inspection(client:&Client,world:&Value)->Value{let world=world.as_str().unwrap().to_string();client.handle.command(move|c|Box::pin(async move{current_paused_inspection(c,&world).await})).await.unwrap()}
