fn paused_report_invariant(release:bool,expected_protected:bool,original:&native_report::Latest,report:&native_report::Latest)->Result<(),&'static str>{
 if release{return Err("Paused callbacks obtained a new play release")}
 if report.observation.protected!=expected_protected{return Err("Frozen observation does not match the phase before callbacks stopped")}
 if report.context!=original.context||report.sequence!=original.sequence||report.observed_at!=original.observed_at||report.digest!=original.digest||report.observation!=original.observation{return Err("Paused callbacks changed the frozen exact engine observation")}
 Ok(())
}
#[test]fn a3_paused_playing_report_does_not_invent_protection_or_allow_stale_release(){
 let observation=native_report::Observation{actual_seed:Some("424242".into()),mods:vec!["noita_together2".into()],complete:true,error:None,beta:None,loaded:true,protected:false,mod_version:"fixture".into(),bridge_version:"fixture".into(),..Default::default()};
 let original=native_report::Latest{context:[1;16],sequence:70,digest:observation.content_digest().unwrap(),observation,observed_at:Instant::now()};
 assert!(paused_report_invariant(false,false,&original,&original).is_ok(),"Playing callbacks freeze their actual unprotected observation, while current release is revoked");
 assert!(paused_report_invariant(true,false,&original,&original).is_err(),"A historical playing observation must never authorize a fresh release while paused");
 assert!(paused_report_invariant(false,true,&original,&original).is_err(),"Staging pause retains its stricter protected-observation requirement");
 for field in 0..5{let mut changed=original.clone();match field{0=>changed.context=[2;16],1=>changed.sequence+=1,2=>changed.observed_at+=Duration::from_millis(1),3=>changed.digest=[9;32],_=>changed.observation.actual_seed=Some("999".into())};assert!(paused_report_invariant(false,false,&original,&changed).is_err(),"Changed frozen report field {field} was accepted");}
 let mut staged=original.clone();staged.observation.protected=true;staged.digest=staged.observation.content_digest().unwrap();assert!(paused_report_invariant(false,true,&staged,&staged).is_ok());assert!(paused_report_invariant(true,true,&staged,&staged).is_err());
}
async fn paused_wait_phase(service:&mut Service,client:&Client,native:&Native,world:&Value,seconds:u64,expected_protected:bool)->(native_report::Latest,Value){
 if !expected_protected{wait(service,client,"playing before callback pause",15,|v|current_state_is(v,"Playing")&&client.pending.lock().unwrap().as_ref().is_some_and(|p|p.release&&p.observation.as_ref().is_some_and(|r|!r.observation.protected))).await;}
 let playing_owner=if expected_protected{None}else{Some(client.pending.lock().unwrap().as_ref().unwrap().owner.expect("Playing pause requires the actual native owner"))};
 fixture_input_write(native.root.join("pause-game-thread"),b"stop real engine callback production only").unwrap();wait(service,client,"paused game callbacks held with connected app",15,|v|native.root.join("game-thread-paused").is_file()&&v["connection"]["state"]=="Checking"&&v["rejoin"]["waiting_for_game"]==true&&v["connection"]["app_connected"]==true).await;
 // Let any already submitted fresh request settle before capturing the exact
 // service inspection. The game callback producer remains stopped throughout.
 let settle=Instant::now()+Duration::from_secs(4);while Instant::now()<settle{service.wall_clock();tokio::time::sleep(Duration::from_millis(250)).await;}
 let pending=client.pending.lock().unwrap().clone().unwrap();let original=pending.observation.clone().unwrap();let owner=pending.owner;let inspected=paused_inspection(client,world).await;let canonical=server_world(service,world);let until=Instant::now()+Duration::from_secs(seconds);let mut next=Instant::now();
 if let Some(before)=playing_owner{assert_eq!(owner,Some(before),"Playing callback pause replaced its native owner before capture");}
 fixture_input_write(native.root.join("pause-observation.json"),serde_json::to_vec_pretty(&json!({"expectedProtected":expected_protected,"release":pending.release,"observationProtected":original.observation.protected,"sequence":original.sequence,"ownerPid":owner.map(|o|o.0),"state":client.handle.view()["connection"]["state"],"engineFactsInjected":true,"serviceMocked":false})).unwrap()).unwrap();
 while Instant::now()<until{service.wall_clock();let view=client.handle.view();let pending=client.pending.lock().unwrap().clone().unwrap();let report=pending.observation.as_ref().unwrap();assert_eq!(pending.owner,owner);paused_report_invariant(pending.release,expected_protected,&original,report).expect("Paused exact observation/release invariant");assert_eq!(view["connection"]["state"],"Checking");assert_eq!(view["rejoin"]["waiting_for_game"],true);assert_eq!(view["connection"]["app_connected"],true);assert_eq!(view["rejoin"]["current_world"],*world);assert!(native.child.try_wait().unwrap().is_none());if Instant::now()>=next{boundary_snapshot(client,"paused native contact with unchanged engine observation");next=Instant::now()+Duration::from_secs(10);}tokio::time::sleep(Duration::from_millis(250)).await;}
 assert_eq!(paused_inspection(client,world).await,inspected,"Held renewal rewrote service inspection");assert_eq!(server_world(service,world),canonical,"Held renewal changed canonical owner");(original,inspected)
}
